('index', 'index.text.017', 'text', 'InsurNex', 'InsurNex', 'InsurNex', 'InsurNex', null, null, null, 170, false),
('index', 'index.text.018', 'text', 'INSURANCE AWARENESS & CUSTOMER SOLUTIONS', 'منصة توعية وحلول تأمينية', 'INSURANCE AWARENESS & CUSTOMER SOLUTIONS', 'منصة توعية وحلول تأمينية', null, null, null, 180, false),
('index', 'index.text.019', 'text', 'iNex helps you understand what insurance covers, where its limits and exclusions apply, and what to ask before', 'تساعدك iNex على فهم التغطيات وحدودها واستثناءاتها قبل اتخاذ القرار. راجع احتياجات الحماية، ونظّم معلومات وثائق', 'iNex helps you understand what insurance covers, where its limits and exclusions apply, and what to ask before you decide. Review your protection needs, organise policy information and explore digital customer services in one clearer journey.', 'تساعدك iNex على فهم التغطيات وحدودها واستثناءاتها قبل اتخاذ القرار. راجع احتياجات الحماية، ونظّم معلومات وثائقك، واستكشف خدمات العملاء الرقمية في تجربة واحدة واضحة.', null, null, null, 190, false),
