('index', 'index.text.037', 'text', 'Assess your protection needs', 'قيّم احتياجات الحماية', 'Assess your protection needs', 'قيّم احتياجات الحماية', null, null, null, 370, false),
('index', 'index.text.038', 'text', 'Explore options with confidence', 'استكشف الخيارات بثقة', 'Explore options with confidence', 'استكشف الخيارات بثقة', null, null, null, 380, false),
('index', 'index.text.039', 'text', 'WHY iNEX?', 'لماذا iNex؟', 'WHY iNEX?', 'لماذا iNex؟', null, null, null, 390, false),
('index', 'index.text.040', 'text', 'Insurance policies can be dense. Understanding begins with knowing what is covered, what is excluded and where', 'قد تبدو وثيقة التأمين مليئة بالتفاصيل، لكن فهمها يبدأ بمعرفة ما تغطيه وما تستثنيه وأين تنتهي حدود الحماية. الو', 'Insurance policies can be dense. Understanding begins with knowing what is covered, what is excluded and where the limits apply. Awareness helps you ask sharper questions and review options on the basis of protection fit—not price alone.', 'قد تبدو وثيقة التأمين مليئة بالتفاصيل، لكن فهمها يبدأ بمعرفة ما تغطيه وما تستثنيه وأين تنتهي حدود الحماية. الوعي يساعدك على طرح أسئلة أدق ومراجعة الاختيارات بناءً على ملاءمة التغطية لاحتياجاتك، لا السعر وحده.', null, null, null, 400, false),
('index', 'index.text.041', 'text', 'Learn before you choose', 'تعرّف قبل أن تختار', 'Learn before you choose', 'تعرّف قبل أن تختار', null, null, null, 410, false),
('index', 'index.text.042', 'text', 'Understand coverage, benefits, limits, exclusions and deductibles — and the terms used in your policy.', 'افهم الفرق بين التغطية والمنفعة والحدود والاستثناءات والتحمل، وتعرّف على المصطلحات التي تظهر في وثيقتك.', 'Understand coverage, benefits, limits, exclusions and deductibles — and the terms used in your policy.', 'افهم الفرق بين التغطية والمنفعة والحدود والاستثناءات والتحمل، وتعرّف على المصطلحات التي تظهر في وثيقتك.', null, null, null, 420, false),
('index', 'index.text.043', 'text', 'Explore awareness →', 'استكشف مركز التوعية ←', 'Explore awareness →', 'استكشف مركز التوعية ←', null, null, null, 430, false),
('index', 'index.text.044', 'text', 'Understand your protection needs', 'افهم احتياجات حمايتك', 'Understand your protection needs', 'افهم احتياجات حمايتك', null, null, null, 440, false),
('index', 'index.text.045', 'text', 'Review your personal or family needs, identify existing protection and highlight questions worth discussing wi', 'راجع احتياجاتك الشخصية أو الأسرية، وحدد جوانب الحماية القائمة والنقاط التي تستحق مناقشتها مع المختص.', 'Review your personal or family needs, identify existing protection and highlight questions worth discussing with a professional.', 'راجع احتياجاتك الشخصية أو الأسرية، وحدد جوانب الحماية القائمة والنقاط التي تستحق مناقشتها مع المختص.', null, null, null, 450, false),
('index', 'index.text.046', 'text', 'Explore solutions →', 'تعرف على الحلول ←', 'Explore solutions →', 'تعرف على الحلول ←', null, null, null, 460, false),
('index', 'index.text.047', 'text', 'Explore available options', 'استكشف الخيارات المتاحة', 'Explore available options', 'استكشف الخيارات المتاحة', null, null, null, 470, false),
('index', 'index.text.048', 'text', 'Follow your requests and explore available quotations through the broker. Compare benefits, limits, exclusions', 'تابع طلباتك واستكشف العروض المتاحة من خلال الوسيط، وقارن المنافع والحدود والاستثناءات وشروط الخدمة قبل الاختيا', 'Follow your requests and explore available quotations through the broker. Compare benefits, limits, exclusions and service terms before choosing.', 'تابع طلباتك واستكشف العروض المتاحة من خلال الوسيط، وقارن المنافع والحدود والاستثناءات وشروط الخدمة قبل الاختيار.', null, null, null, 480, false),
