('index', 'index.text.103', 'text', 'Explore the insurance awareness hub →', 'اكتشف مركز التوعية التأمينية ←', 'Explore the insurance awareness hub →', 'اكتشف مركز التوعية التأمينية ←', null, null, null, 1030, false),
('index', 'index.image.03', 'image', 'Digital insurance technology illustration showing a connected dashboard, mobile device and protection shield', 'Digital insurance technology illustration showing a connected dashboard, mobile device and protection shield', null, null, 'Digital insurance technology illustration showing a connected dashboard, mobile device and protection shield', 'Digital insurance technology illustration showing a connected dashboard, mobile device and protection shield', '/assets/insurtech-illustration.svg', 1030, false),
('index', 'index.text.104', 'text', 'INSURANCE TECHNOLOGY · INSURTECH', 'التكنولوجيا التأمينية InsurTech', 'INSURANCE TECHNOLOGY · INSURTECH', 'التكنولوجيا التأمينية InsurTech', null, null, null, 1040, false),
('index', 'index.text.105', 'text', 'iNex brings education closer to practical support: clear explanations, tools to review protection needs, and s', 'تربط iNex بين المعرفة والخدمات الرقمية العملية: شرح مبسط للمفاهيم، وأدوات لمراجعة احتياجات الحماية، وخدمات تسا', 'iNex brings education closer to practical support: clear explanations, tools to review protection needs, and services that help customers organise policy information, requests and next steps. Technology should make the journey clearer and easier—not introduce another layer of complexity.', 'تربط iNex بين المعرفة والخدمات الرقمية العملية: شرح مبسط للمفاهيم، وأدوات لمراجعة احتياجات الحماية، وخدمات تساعد على تنظيم معلومات الوثائق والطلبات والخطوات التالية. هدف التقنية هنا أن تجعل الرحلة أوضح وأسهل، لا أن تضيف إليها تعقيدًا جديدًا.', null, null, null, 1050, false),
('index', 'index.text.106', 'text', 'Clear information', 'معلومة مفهومة', 'Clear information', 'معلومة مفهومة', null, null, null, 1060, false),
('index', 'index.text.107', 'text', 'More informed assessment', 'تقييم أكثر وعيًا', 'More informed assessment', 'تقييم أكثر وعيًا', null, null, null, 1070, false),
('index', 'index.text.108', 'text', 'Services in one experience', 'خدمات في تجربة واحدة', 'Services in one experience', 'خدمات في تجربة واحدة', null, null, null, 1080, false),
('index', 'index.text.109', 'text', 'Discover how iNex works ↗', 'اكتشف كيف تعمل iNex ↗', 'Discover how iNex works ↗', 'اكتشف كيف تعمل iNex ↗', null, null, null, 1090, false),
('index', 'index.text.110', 'text', 'THE iNEX ECOSYSTEM', 'منظومة iNex وشريكها الاستراتيجي', 'THE iNEX ECOSYSTEM', 'منظومة iNex وشريكها الاستراتيجي', null, null, null, 1100, false),
('index', 'index.text.111', 'text', 'The ecosystem brings together two distinct digital products with complementary ambitions and separate audience', 'تضم المنظومة منتجين رقميين متكاملين في الرؤية، مستقلين في الوظيفة والجمهور: iNex لرفع وعي العملاء وتسهيل رحلته', 'The ecosystem brings together two distinct digital products with complementary ambitions and separate audiences: iNex helps customers build insurance awareness and navigate digital services, while InsurNex supports insurance brokers in their professional work. Each product has its own experience and purpose.', 'تضم المنظومة منتجين رقميين متكاملين في الرؤية، مستقلين في الوظيفة والجمهور: iNex لرفع وعي العملاء وتسهيل رحلتهم الرقمية، وInsurNex لدعم وسطاء التأمين في إدارة أعمالهم المهنية. لكل منتج تجربته ومساره الخاص.', null, null, null, 1110, false),
('index', 'index.text.112', 'text', 'FOR CUSTOMERS', 'للعملاء والأفراد', 'FOR CUSTOMERS', 'للعملاء والأفراد', null, null, null, 1120, false),
('index', 'index.text.113', 'text', 'A customer-facing awareness and solutions platform that helps people understand insurance, review protection n', 'منصة موجهة للعملاء تساعد الأفراد على فهم التأمين ومراجعة احتياجات الحماية والوصول إلى المعلومات والخدمات الرقم', 'A customer-facing awareness and solutions platform that helps people understand insurance, review protection needs and access available information and digital services through a clearer experience.', 'منصة موجهة للعملاء تساعد الأفراد على فهم التأمين ومراجعة احتياجات الحماية والوصول إلى المعلومات والخدمات الرقمية المتاحة عبر تجربة مبسطة.', null, null, null, 1130, false),
('index', 'index.text.114', 'text', 'Get started with iNex ↗', 'ابدأ مع iNex ↗', 'Get started with iNex ↗', 'ابدأ مع iNex ↗', null, null, null, 1140, false),
('index', 'index.text.115', 'text', 'SEPARATE PLATFORM · FOR BROKERS', 'منصة مستقلة · لوسطاء التأمين', 'SEPARATE PLATFORM · FOR BROKERS', 'منصة مستقلة · لوسطاء التأمين', null, null, null, 1150, false),
('index', 'index.text.116', 'text', 'A separate digital assistant for insurance brokers, supporting day-to-day brokerage work through tools designe', 'مساعد رقمي مستقل لوسطاء التأمين، يساند تنظيم العمل اليومي وعمليات الوساطة من خلال أدوات مخصصة للقطاع، ويعمل ضم', 'A separate digital assistant for insurance brokers, supporting day-to-day brokerage work through tools designed for the sector. It operates as a distinct product, separate from the iNex customer experience.', 'مساعد رقمي مستقل لوسطاء التأمين، يساند تنظيم العمل اليومي وعمليات الوساطة من خلال أدوات مخصصة للقطاع، ويعمل ضمن تجربة مختلفة عن iNex.', null, null, null, 1160, false),
('index', 'index.text.117', 'text', 'Explore InsurNex ↗', 'اكتشف InsurNex ↗', 'Explore InsurNex ↗', 'اكتشف InsurNex ↗', null, null, null, 1170, false),
('index', 'index.text.118', 'text', 'iNex serves customers through awareness and digital solutions, while InsurNex serves insurance brokers. Each p', 'تخدم iNex العملاء والتوعية والحلول الرقمية، بينما يخدم InsurNex وسطاء التأمين. لكل منصة جمهورها ووظيفتها وتجرب', 'iNex serves customers through awareness and digital solutions, while InsurNex serves insurance brokers. Each platform has its own audience, purpose and product experience; neither is a user interface for the other.', 'تخدم iNex العملاء والتوعية والحلول الرقمية، بينما يخدم InsurNex وسطاء التأمين. لكل منصة جمهورها ووظيفتها وتجربتها المستقلة، ولا تمثل إحداهما واجهة للمنتج الآخر.', null, null, null, 1180, false),
('index', 'index.text.119', 'text', 'LEADERSHIP AT iNEX', 'قيادة iNex', 'LEADERSHIP AT iNEX', 'قيادة iNex', null, null, null, 1190, false),
('index', 'index.text.120', 'text', 'iNex is led by a founding team bringing together strategic direction and operations to build a digital experie', 'يقود iNex فريق مؤسس يجمع بين الرؤية الاستراتيجية والتشغيل، بهدف بناء تجربة رقمية تضع احتياجات العميل والوضوح و', 'iNex is led by a founding team bringing together strategic direction and operations to build a digital experience centred on customer needs, clarity and trust.', 'يقود iNex فريق مؤسس يجمع بين الرؤية الاستراتيجية والتشغيل، بهدف بناء تجربة رقمية تضع احتياجات العميل والوضوح والثقة في المقدمة.', null, null, null, 1200, false),
('index', 'index.image.04', 'image', 'Islam Ibrahim, CEO and Founder of iNex', 'Islam Ibrahim, CEO and Founder of iNex', null, null, 'Islam Ibrahim, CEO and Founder of iNex', 'Islam Ibrahim, CEO and Founder of iNex', '/assets/ceo-portrait-clean.png', 1040, false),
('index', 'index.text.121', 'text', 'CEO & Founder', 'الرئيس التنفيذي والمؤسس', 'CEO & Founder', 'الرئيس التنفيذي والمؤسس', null, null, null, 1210, false),
('index', 'index.text.122', 'text', 'Islam Ibrahim', 'إسلام إبراهيم', 'Islam Ibrahim', 'إسلام إبراهيم', null, null, null, 1220, false),
('index', 'index.text.123', 'text', 'Leads iNex’s strategic vision and digital experience, with a focus on making insurance easier to understand an', 'يقود الرؤية الاستراتيجية وتطوير تجربة iNex الرقمية، مع التركيز على جعل التأمين أكثر فهمًا واتصالًا باحتياجات ا', 'Leads iNex’s strategic vision and digital experience, with a focus on making insurance easier to understand and more connected to customer needs.', 'يقود الرؤية الاستراتيجية وتطوير تجربة iNex الرقمية، مع التركيز على جعل التأمين أكثر فهمًا واتصالًا باحتياجات العملاء.', null, null, null, 1230, false),
('index', 'index.text.124', 'text', 'Islam Ibrahim on LinkedIn ↗', 'LinkedIn إسلام إبراهيم ↗', 'Islam Ibrahim on LinkedIn ↗', 'LinkedIn إسلام إبراهيم ↗', null, null, null, 1240, false),
('index', 'index.image.05', 'image', 'Fawzya Hesham, COO and Co-Founder of iNex', 'Fawzya Hesham, COO and Co-Founder of iNex', null, null, 'Fawzya Hesham, COO and Co-Founder of iNex', 'Fawzya Hesham, COO and Co-Founder of iNex', '/assets/fawzya-hesham.jpg', 1050, false),
('index', 'index.text.125', 'text', 'COO & Co-Founder', 'الرئيس التنفيذي للعمليات والشريك المؤسس', 'COO & Co-Founder', 'الرئيس التنفيذي للعمليات والشريك المؤسس', null, null, null, 1250, false),
('index', 'index.text.126', 'text', 'Fawzya Hesham', 'فوزية هشام', 'Fawzya Hesham', 'فوزية هشام', null, null, null, 1260, false),
('index', 'index.text.127', 'text', 'Leads operational direction and coordinates platform priorities, supporting a consistent digital experience fo', 'تقود التوجه التشغيلي وتنسيق تنفيذ أولويات المنصة، بما يدعم تقديم تجربة رقمية منظمة ومتسقة تركز على جودة الخدمة', 'Leads operational direction and coordinates platform priorities, supporting a consistent digital experience focused on service quality and customer needs.', 'تقود التوجه التشغيلي وتنسيق تنفيذ أولويات المنصة، بما يدعم تقديم تجربة رقمية منظمة ومتسقة تركز على جودة الخدمة واحتياجات العملاء.', null, null, null, 1270, false),
('index', 'index.text.128', 'text', 'Fawzya Hesham on LinkedIn ↗', 'LinkedIn فوزية هشام ↗', 'Fawzya Hesham on LinkedIn ↗', 'LinkedIn فوزية هشام ↗', null, null, null, 1280, false),
('index', 'index.text.129', 'text', 'Meet the leadership team →', 'تعرف على فريق القيادة ←', 'Meet the leadership team →', 'تعرف على فريق القيادة ←', null, null, null, 1290, false),
('index', 'index.text.130', 'text', 'A CLEARER WAY TO DECIDE', 'A CLEARER WAY TO DECIDE', 'A CLEARER WAY TO DECIDE', 'A CLEARER WAY TO DECIDE', null, null, null, 1300, false),
('index', 'index.text.131', 'text', 'Before choosing insurance, define what you want to protect, what you need to understand and what you should ve', 'قبل اختيار تغطية تأمينية، حدّد ما تريد حمايته، وما الذي تحتاج إلى فهمه، وما الذي ينبغي التحقق منه. تساعدك هذه ', 'Before choosing insurance, define what you want to protect, what you need to understand and what you should verify. These questions turn information into practical next steps.', 'قبل اختيار تغطية تأمينية، حدّد ما تريد حمايته، وما الذي تحتاج إلى فهمه، وما الذي ينبغي التحقق منه. تساعدك هذه الأسئلة على تحويل المعلومات إلى خطوات عملية.', null, null, null, 1310, false),
('index', 'index.text.132', 'text', 'What do I want to protect?', 'ما الذي أريد حمايته؟', 'What do I want to protect?', 'ما الذي أريد حمايته؟', null, null, null, 1320, false),
('index', 'index.text.133', 'text', 'Identify the people, property or commitments that matter to you, and consider how a potential loss could affec', 'حدّد الأشخاص أو الممتلكات أو الالتزامات التي تهمك، وفكّر في أثر الخطر المحتمل على حياتك أو عملك.', 'Identify the people, property or commitments that matter to you, and consider how a potential loss could affect your life or work.', 'حدّد الأشخاص أو الممتلكات أو الالتزامات التي تهمك، وفكّر في أثر الخطر المحتمل على حياتك أو عملك.', null, null, null, 1330, false),
('index', 'index.text.134', 'text', 'What does the policy cover?', 'ما الذي تغطيه الوثيقة؟', 'What does the policy cover?', 'ما الذي تغطيه الوثيقة؟', null, null, null, 1340, false),
('index', 'index.text.135', 'text', 'Review benefits, limits, exclusions, deductibles and the policy period. Do not rely on the product name alone.', 'راجع المنافع وحدود المسؤولية والاستثناءات والتحملات وفترة سريان الوثيقة، ولا تعتمد على اسم المنتج وحده.', 'Review benefits, limits, exclusions, deductibles and the policy period. Do not rely on the product name alone.', 'راجع المنافع وحدود المسؤولية والاستثناءات والتحملات وفترة سريان الوثيقة، ولا تعتمد على اسم المنتج وحده.', null, null, null, 1350, false),
('index', 'index.text.136', 'text', 'What should I compare?', 'ما الذي أحتاج إلى مقارنته؟', 'What should I compare?', 'ما الذي أحتاج إلى مقارنته؟', null, null, null, 1360, false),
('index', 'index.text.137', 'text', 'Compare like for like: coverage scope, terms, claims procedures and services—then assess price in context.', 'قارن العروض على أساس متكافئ: نطاق التغطية والشروط وإجراءات المطالبة والخدمات، ثم انظر إلى السعر في سياقه.', 'Compare like for like: coverage scope, terms, claims procedures and services—then assess price in context.', 'قارن العروض على أساس متكافئ: نطاق التغطية والشروط وإجراءات المطالبة والخدمات، ثم انظر إلى السعر في سياقه.', null, null, null, 1370, false),
('index', 'index.text.138', 'text', 'Who can clarify what I do not understand?', 'من يوضح ما لا أفهمه؟', 'Who can clarify what I do not understand?', 'من يوضح ما لا أفهمه؟', null, null, null, 1380, false),
('index', 'index.text.139', 'text', 'Prepare your questions and discuss the details with your insurance broker or insurer before making a final dec', 'جهّز أسئلتك وناقش التفاصيل مع وسيط التأمين أو شركة التأمين قبل اتخاذ قرارك النهائي.', 'Prepare your questions and discuss the details with your insurance broker or insurer before making a final decision.', 'جهّز أسئلتك وناقش التفاصيل مع وسيط التأمين أو شركة التأمين قبل اتخاذ قرارك النهائي.', null, null, null, 1390, false),
('index', 'index.text.140', 'text', 'THE iNex APPROACH', 'THE iNex APPROACH', 'THE iNex APPROACH', 'THE iNex APPROACH', null, null, null, 1400, false),
('index', 'index.text.141', 'text', 'From information to clearer decisions, and from decisions to practical next steps.', 'من المعلومة إلى قرار أوضح، ومن القرار إلى خطوة عملية.', 'From information to clearer decisions,<br><em>and from decisions to practical next steps.</em>', 'من المعلومة إلى قرار أوضح،<br><em>ومن القرار إلى خطوة عملية.</em>', null, null, null, 1410, false),
('index', 'index.text.142', 'text', 'Insurance is more than a product choice. It is a set of terms, benefits and limits connected to people, assets', 'التأمين ليس مجرد منتج تختاره؛ إنه مجموعة شروط ومنافع وحدود ترتبط بأشخاص وأصول ومسؤوليات. تساعدك iNex على ترتيب', 'Insurance is more than a product choice. It is a set of terms, benefits and limits connected to people, assets and responsibilities. iNex helps you make sense of the details that matter, so you can approach conversations with a broker or insurer better prepared.', 'التأمين ليس مجرد منتج تختاره؛ إنه مجموعة شروط ومنافع وحدود ترتبط بأشخاص وأصول ومسؤوليات. تساعدك iNex على ترتيب الصورة وفهم ما يستحق الانتباه، لتدخل نقاشك مع الوسيط أو شركة التأمين وأنت أكثر استعدادًا.', null, null, null, 1420, false),
('index', 'index.text.143', 'text', 'Understand the language', 'افهم ما وراء المصطلحات', 'Understand the language', 'افهم ما وراء المصطلحات', null, null, null, 1430, false),
('index', 'index.text.144', 'text', 'Start with the details that shape a policy: coverage, benefits, limits, exclusions and deductibles. Understand', 'ابدأ بالمفاهيم التي تصنع الفرق: التغطية، والمنفعة، والحد، والاستثناء، والتحمل. فهم هذه العناصر يمنحك أساسًا أف', 'Start with the details that shape a policy: coverage, benefits, limits, exclusions and deductibles. Understanding these elements gives you a stronger basis for reading a policy than relying on a product name alone.', 'ابدأ بالمفاهيم التي تصنع الفرق: التغطية، والمنفعة، والحد، والاستثناء، والتحمل. فهم هذه العناصر يمنحك أساسًا أفضل لقراءة الوثيقة بدل الاعتماد على اسم المنتج وحده.', null, null, null, 1440, false),
('index', 'index.text.145', 'text', 'Connect protection to your needs', 'اربط الحماية باحتياجك', 'Connect protection to your needs', 'اربط الحماية باحتياجك', null, null, null, 1450, false),
('index', 'index.text.146', 'text', 'Priorities differ across personal, family and work contexts. Review what you want to protect, what is already ', 'تختلف الأولويات باختلاف الحياة والعمل والأسرة. راجع ما تريد حمايته، وما لديك بالفعل، والأسئلة التي تحتاج إلى م', 'Priorities differ across personal, family and work contexts. Review what you want to protect, what is already in place and which questions deserve attention before comparing options.', 'تختلف الأولويات باختلاف الحياة والعمل والأسرة. راجع ما تريد حمايته، وما لديك بالفعل، والأسئلة التي تحتاج إلى مناقشتها قبل مقارنة الخيارات.', null, null, null, 1460, false),
('index', 'index.text.147', 'text', 'Take a more informed next step', 'تحرك بخطوة أكثر وعيًا', 'Take a more informed next step', 'تحرك بخطوة أكثر وعيًا', null, null, null, 1470, false),
('index', 'index.text.148', 'text', 'Use the iNex tools available to organise information, explore services and follow your requests. Then refer to', 'استخدم أدوات iNex المتاحة لتنظيم معلوماتك واستكشاف الخدمات وطلباتك، ثم ارجع إلى الوسيط أو شركة التأمين لتأكيد ', 'Use the iNex tools available to organise information, explore services and follow your requests. Then refer to your broker or insurer to confirm the details and terms that apply to your circumstances.', 'استخدم أدوات iNex المتاحة لتنظيم معلوماتك واستكشاف الخدمات وطلباتك، ثم ارجع إلى الوسيط أو شركة التأمين لتأكيد التفاصيل والشروط الخاصة بحالتك.', null, null, null, 1480, false),
