('index', 'index.text.158', 'text', 'Notice', 'تنويه', 'Notice', 'تنويه', null, null, null, 1580, false),
('index', 'index.text.159', 'text', 'Content is for general awareness and does not replace policy terms or professional advice. iNex is not an insu', 'المحتوى للتوعية العامة ولا يحل محل شروط الوثيقة أو الاستشارة المتخصصة. iNex ليست شركة تأمين ولا تصدر الوثائق.', 'Content is for general awareness and does not replace policy terms or professional advice. iNex is not an insurer and does not issue policies.', 'المحتوى للتوعية العامة ولا يحل محل شروط الوثيقة أو الاستشارة المتخصصة. iNex ليست شركة تأمين ولا تصدر الوثائق.', null, null, null, 1590, false),
('index', 'index.text.160', 'text', 'Follow iNex & meet the founders', 'تابعنا وتواصل مع المؤسسين', 'Follow iNex & meet the founders', 'تابعنا وتواصل مع المؤسسين', null, null, null, 1600, false),
