('platform', 'platform.text.017', 'text', 'InsurNex', 'InsurNex', 'InsurNex', 'InsurNex', null, null, null, 170, false),
('platform', 'platform.text.018', 'text', 'THE iNEX PLATFORM', 'منصة iNex', 'THE iNEX PLATFORM', 'منصة iNex', null, null, null, 180, false),
('platform', 'platform.text.019', 'text', 'iNex combines insurance education and digital customer services to help you understand what you read, review w', 'تجمع iNex بين التوعية التأمينية والخدمات الرقمية لتساعدك على فهم ما تقرأه، ومراجعة ما تحتاج إليه، وتنظيم المعل', 'iNex combines insurance education and digital customer services to help you understand what you read, review what you need and organise the information and requests available in your account. It connects knowledge with practical next steps while making clear when to consult your broker or insurer.', 'تجمع iNex بين التوعية التأمينية والخدمات الرقمية لتساعدك على فهم ما تقرأه، ومراجعة ما تحتاج إليه، وتنظيم المعلومات والطلبات المتاحة في حسابك. إنها تجربة تربط المعرفة بالخطوات العملية، مع توضيح متى تحتاج إلى الرجوع للوسيط أو شركة التأمين.', null, null, null, 190, false),
('platform', 'platform.text.020', 'text', 'WHAT THE PLATFORM OFFERS', 'ماذا تقدم المنصة؟', 'WHAT THE PLATFORM OFFERS', 'ماذا تقدم المنصة؟', null, null, null, 200, false),
('platform', 'platform.text.021', 'text', 'The capabilities below are based on the current iNex application. Availability may vary by account type, confi', 'الوظائف التالية مستندة إلى تطبيق iNex الحالي. قد يختلف توفر بعض الخدمات وفق نوع الحساب والإعدادات وشروط مقدمي ', 'The capabilities below are based on the current iNex application. Availability may vary by account type, configuration and insurance provider terms.', 'الوظائف التالية مستندة إلى تطبيق iNex الحالي. قد يختلف توفر بعض الخدمات وفق نوع الحساب والإعدادات وشروط مقدمي التأمين.', null, null, null, 210, false),
('platform', 'platform.text.022', 'text', 'Insurance tips & information', 'نصائح ومعلومات تأمينية', 'Insurance tips & information', 'نصائح ومعلومات تأمينية', null, null, null, 220, false),
('platform', 'platform.text.023', 'text', 'Explore insurance types, coverage, benefits, exclusions, deductibles, claims and renewals. Understand the lang', 'تعرّف على أنواع التأمين ومفاهيم التغطية والمنافع والاستثناءات والتحملات والمطالبات والتجديد. افهم المصطلحات ال', 'Explore insurance types, coverage, benefits, exclusions, deductibles, claims and renewals. Understand the language used in your policy, know where to look for key details and prepare the questions worth asking.', 'تعرّف على أنواع التأمين ومفاهيم التغطية والمنافع والاستثناءات والتحملات والمطالبات والتجديد. افهم المصطلحات التي تقرؤها، واعرف أين تبحث داخل الوثيقة، وما الأسئلة التي ينبغي طرحها.', null, null, null, 230, false),
('platform', 'platform.text.024', 'text', 'Protection assessment', 'تقييم الحماية', 'Protection assessment', 'تقييم الحماية', null, null, null, 240, false),
('platform', 'platform.text.025', 'text', 'Structure your view of personal or family protection needs and identify areas to review or discuss with an ins', 'نظّم نظرتك إلى احتياجات الحماية الشخصية أو الأسرية، وحدد الجوانب التي تحتاج إلى مراجعة أو مناقشة مع وسيط التأم', 'Structure your view of personal or family protection needs and identify areas to review or discuss with an insurance broker.', 'نظّم نظرتك إلى احتياجات الحماية الشخصية أو الأسرية، وحدد الجوانب التي تحتاج إلى مراجعة أو مناقشة مع وسيط التأمين.', null, null, null, 250, false),
('platform', 'platform.text.026', 'text', 'Your policies & documents', 'وثائقك ومستنداتك', 'Your policies & documents', 'وثائقك ومستنداتك', null, null, null, 260, false),
('platform', 'platform.text.027', 'text', 'View policies registered to your account, upload relevant documents and keep track of renewal dates. The polic', 'اعرض الوثائق المسجلة في حسابك، وارفع المستندات ذات الصلة، وتابع تواريخ التجديد. تظل الوثيقة الصادرة عن شركة ال', 'View policies registered to your account, upload relevant documents and keep track of renewal dates. The policy issued by the insurer remains the authoritative record of coverage terms.', 'اعرض الوثائق المسجلة في حسابك، وارفع المستندات ذات الصلة، وتابع تواريخ التجديد. تظل الوثيقة الصادرة عن شركة التأمين هي المرجع المعتمد لشروط التغطية.', null, null, null, 270, false),
('platform', 'platform.text.028', 'text', 'Quote requests', 'طلبات عروض الأسعار', 'Quote requests', 'طلبات عروض الأسعار', null, null, null, 280, false),
('platform', 'platform.text.029', 'text', 'Submit a quotation request, follow the options made available through the broker, and review differences in be', 'قدّم طلب عرض سعر، وتابع الخيارات التي يتيحها الوسيط، وراجع الفروق في المنافع وحدود التغطية والاستثناءات والشرو', 'Submit a quotation request, follow the options made available through the broker, and review differences in benefits, coverage limits, exclusions and terms before deciding.', 'قدّم طلب عرض سعر، وتابع الخيارات التي يتيحها الوسيط، وراجع الفروق في المنافع وحدود التغطية والاستثناءات والشروط قبل اتخاذ القرار.', null, null, null, 290, false),
('platform', 'platform.text.030', 'text', 'Consultations & customer care', 'الاستشارات وخدمة العملاء', 'Consultations & customer care', 'الاستشارات وخدمة العملاء', null, null, null, 300, false),
('platform', 'platform.text.031', 'text', 'Request a consultation or appointment, submit an enquiry or complaint through the channels available in the ap', 'قدّم طلب استشارة أو موعد، وأرسل استفساراتك أو شكواك عبر القنوات المتاحة في التطبيق، وتواصل مع الوسيط عند الحاج', 'Request a consultation or appointment, submit an enquiry or complaint through the channels available in the app, and contact the broker when you need clarification about a request or policy.', 'قدّم طلب استشارة أو موعد، وأرسل استفساراتك أو شكواك عبر القنوات المتاحة في التطبيق، وتواصل مع الوسيط عند الحاجة إلى توضيح يتعلق بطلبك أو وثيقتك.', null, null, null, 310, false),
('platform', 'platform.text.032', 'text', 'InsuraPoints', 'InsuraPoints', 'InsuraPoints', 'InsuraPoints', null, null, null, 320, false),
('platform', 'platform.text.033', 'text', 'The programme provides a points and rewards mechanism linked to insurance, wellness and safe-driving activitie', 'يوفر البرنامج نظام نقاط ومكافآت مرتبطًا بأنشطة تأمينية وصحية وسلوكيات قيادة آمنة، وفق شروط البرنامج وآليات احت', 'The programme provides a points and rewards mechanism linked to insurance, wellness and safe-driving activities, subject to programme rules and the applicable points criteria.', 'يوفر البرنامج نظام نقاط ومكافآت مرتبطًا بأنشطة تأمينية وصحية وسلوكيات قيادة آمنة، وفق شروط البرنامج وآليات احتساب النقاط المعتمدة.', null, null, null, 330, false),
('platform', 'platform.text.034', 'text', 'YOUR iNEX JOURNEY', 'رحلتك مع iNex', 'YOUR iNEX JOURNEY', 'رحلتك مع iNex', null, null, null, 340, false),
('platform', 'platform.text.035', 'text', 'Learn', 'تعلّم', 'Learn', 'تعلّم', null, null, null, 350, false),
('platform', 'platform.text.036', 'text', 'Start with clear insurance information.', 'ابدأ بمعلومة تأمينية واضحة.', 'Start with clear insurance information.', 'ابدأ بمعلومة تأمينية واضحة.', null, null, null, 360, false),
('platform', 'platform.text.037', 'text', 'Assess', 'قيّم', 'Assess', 'قيّم', null, null, null, 370, false),
('platform', 'platform.text.038', 'text', 'Review your protection needs.', 'راجع احتياجات الحماية الخاصة بك.', 'Review your protection needs.', 'راجع احتياجات الحماية الخاصة بك.', null, null, null, 380, false),
('platform', 'platform.text.039', 'text', 'Explore', 'استكشف', 'Explore', 'استكشف', null, null, null, 390, false),
('platform', 'platform.text.040', 'text', 'Explore options and request guidance when needed.', 'اطلع على الخيارات واطلب المساعدة عند الحاجة.', 'Explore options and request guidance when needed.', 'اطلع على الخيارات واطلب المساعدة عند الحاجة.', null, null, null, 400, false),
('platform', 'platform.text.041', 'text', 'HOW THE EXPERIENCE WORKS', 'HOW THE EXPERIENCE WORKS', 'HOW THE EXPERIENCE WORKS', 'HOW THE EXPERIENCE WORKS', null, null, null, 410, false),
('platform', 'platform.text.042', 'text', 'You do not need to do everything at once. Use iNex at your own pace: learn first, review your needs, organise ', 'لا تحتاج إلى البدء بكل شيء دفعة واحدة. استخدم iNex بحسب حاجتك: تعلّم أولًا، راجع احتياجاتك، نظّم معلوماتك، ثم ', 'You do not need to do everything at once. Use iNex at your own pace: learn first, review your needs, organise your information and then move to an available service or request guidance.', 'لا تحتاج إلى البدء بكل شيء دفعة واحدة. استخدم iNex بحسب حاجتك: تعلّم أولًا، راجع احتياجاتك، نظّم معلوماتك، ثم انتقل إلى الخدمة المتاحة أو اطلب المساعدة.', null, null, null, 420, false),
('platform', 'platform.text.043', 'text', 'Learn', 'تعلّم', 'Learn', 'تعلّم', null, null, null, 430, false),
('platform', 'platform.text.044', 'text', 'Start with content that explains insurance terms, types and policy components before you compare options.', 'ابدأ بمحتوى يشرح المصطلحات والأنواع ومكونات الوثيقة، حتى تتعرف على الأساسيات قبل مقارنة الخيارات.', 'Start with content that explains insurance terms, types and policy components before you compare options.', 'ابدأ بمحتوى يشرح المصطلحات والأنواع ومكونات الوثيقة، حتى تتعرف على الأساسيات قبل مقارنة الخيارات.', null, null, null, 440, false),
('platform', 'platform.text.045', 'text', 'Assess', 'قيّم', 'Assess', 'قيّم', null, null, null, 450, false),
('platform', 'platform.text.046', 'text', 'Use protection assessment tools to review your needs and identify areas that require more information or discu', 'استخدم أدوات تقييم الحماية لمراجعة احتياجاتك وتحديد الموضوعات التي تحتاج إلى مزيد من الفهم أو النقاش.', 'Use protection assessment tools to review your needs and identify areas that require more information or discussion.', 'استخدم أدوات تقييم الحماية لمراجعة احتياجاتك وتحديد الموضوعات التي تحتاج إلى مزيد من الفهم أو النقاش.', null, null, null, 460, false),
('platform', 'platform.text.047', 'text', 'Organise', 'نظّم', 'Organise', 'نظّم', null, null, null, 470, false),
('platform', 'platform.text.048', 'text', 'Bring policy information, documents and available requests together in your account, and keep track of dates a', 'اجمع معلومات الوثائق والمستندات والطلبات المتاحة في حسابك، وتابع التواريخ والخطوات المرتبطة بها.', 'Bring policy information, documents and available requests together in your account, and keep track of dates and related steps.', 'اجمع معلومات الوثائق والمستندات والطلبات المتاحة في حسابك، وتابع التواريخ والخطوات المرتبطة بها.', null, null, null, 480, false),
('platform', 'platform.text.049', 'text', 'Connect', 'تواصل', 'Connect', 'تواصل', null, null, null, 490, false),
('platform', 'platform.text.050', 'text', 'When you need support, use the consultation and customer-service channels available, or discuss coverage terms', 'عندما تحتاج إلى دعم، استخدم قنوات الاستشارة وخدمة العملاء المتاحة، أو ناقش شروط التغطية مع الوسيط أو شركة التأ', 'When you need support, use the consultation and customer-service channels available, or discuss coverage terms with your broker or insurer.', 'عندما تحتاج إلى دعم، استخدم قنوات الاستشارة وخدمة العملاء المتاحة، أو ناقش شروط التغطية مع الوسيط أو شركة التأمين.', null, null, null, 500, false),
('platform', 'platform.text.051', 'text', 'A PRACTICAL DIGITAL JOURNEY', 'A PRACTICAL DIGITAL JOURNEY', 'A PRACTICAL DIGITAL JOURNEY', 'A PRACTICAL DIGITAL JOURNEY', null, null, null, 510, false),
('platform', 'platform.text.052', 'text', 'More than separate tools, a connected customer journey.', 'ليست مجموعة أدوات منفصلة، بل رحلة مترابطة.', 'More than separate tools,<br><em>a connected customer journey.</em>', 'ليست مجموعة أدوات منفصلة،<br><em>بل رحلة مترابطة.</em>', null, null, null, 520, false),
('platform', 'platform.text.053', 'text', 'A digital platform becomes useful when information, tools and services work together around the customer’s nee', 'تظهر قيمة المنصة عندما تعمل المعلومات والأدوات والخدمات معًا حول احتياج العميل. ابدأ بالتعلّم، ثم استخدم ما فه', 'A digital platform becomes useful when information, tools and services work together around the customer’s needs. Start with learning, then use what you understand to review protection needs, organise information and identify a sensible next step.', 'تظهر قيمة المنصة عندما تعمل المعلومات والأدوات والخدمات معًا حول احتياج العميل. ابدأ بالتعلّم، ثم استخدم ما فهمته لمراجعة احتياجات الحماية وتنظيم معلوماتك وتحديد الخطوة التالية.', null, null, null, 530, false),
('platform', 'platform.text.054', 'text', 'Start with understanding', 'ابدأ بالفهم', 'Start with understanding', 'ابدأ بالفهم', null, null, null, 540, false),
('platform', 'platform.text.055', 'text', 'Explore insurance terms and policy components before requesting a quote or discussing coverage. This helps you', 'تعرّف على المصطلحات ومكونات الوثيقة قبل طلب عرض أو مناقشة تغطية. يساعدك ذلك على تحديد ما تعرفه وما تحتاج إلى ت', 'Explore insurance terms and policy components before requesting a quote or discussing coverage. This helps you distinguish what you understand from what still needs clarification.', 'تعرّف على المصطلحات ومكونات الوثيقة قبل طلب عرض أو مناقشة تغطية. يساعدك ذلك على تحديد ما تعرفه وما تحتاج إلى توضيحه.', null, null, null, 550, false),
('platform', 'platform.text.056', 'text', 'Build a view of your needs', 'كوّن صورة عن احتياجاتك', 'Build a view of your needs', 'كوّن صورة عن احتياجاتك', null, null, null, 560, false),
('platform', 'platform.text.057', 'text', 'Review personal or family protection needs, recognise existing arrangements and identify areas worth discussin', 'راجع احتياجاتك الشخصية أو الأسرية، وحدد جوانب الحماية القائمة والنقاط التي تستحق نقاشًا إضافيًا مع المختص.', 'Review personal or family protection needs, recognise existing arrangements and identify areas worth discussing with a professional.', 'راجع احتياجاتك الشخصية أو الأسرية، وحدد جوانب الحماية القائمة والنقاط التي تستحق نقاشًا إضافيًا مع المختص.', null, null, null, 570, false),
('platform', 'platform.text.058', 'text', 'Organise your information', 'نظّم معلوماتك', 'Organise your information', 'نظّم معلوماتك', null, null, null, 580, false),
('platform', 'platform.text.059', 'text', 'Bring available policy information, documents and requests together in your account, and refer to the original', 'اجمع معلومات الوثائق والمستندات والطلبات المتاحة في حسابك، وارجع إلى الوثيقة الأصلية عند التحقق من أي شرط أو م', 'Bring available policy information, documents and requests together in your account, and refer to the original policy whenever checking a condition or benefit.', 'اجمع معلومات الوثائق والمستندات والطلبات المتاحة في حسابك، وارجع إلى الوثيقة الأصلية عند التحقق من أي شرط أو منفعة.', null, null, null, 590, false),
('platform', 'platform.text.060', 'text', 'Choose your next step', 'اختر خطوتك التالية', 'Choose your next step', 'اختر خطوتك التالية', null, null, null, 600, false),
('platform', 'platform.text.061', 'text', 'Explore available services or submit a request through the app, and consult your broker or insurer when specia', 'استكشف الخدمات المتاحة أو أرسل طلبًا من خلال التطبيق، واستعن بالوسيط أو شركة التأمين عند الحاجة إلى تأكيد أو ت', 'Explore available services or submit a request through the app, and consult your broker or insurer when specialist confirmation or interpretation is needed.', 'استكشف الخدمات المتاحة أو أرسل طلبًا من خلال التطبيق، واستعن بالوسيط أو شركة التأمين عند الحاجة إلى تأكيد أو تفسير متخصص.', null, null, null, 610, false),
