('solutions', 'solutions.text.018', 'text', 'CUSTOMER-CENTRED SOLUTIONS', 'حلول تتمحور حول العميل', 'CUSTOMER-CENTRED SOLUTIONS', 'حلول تتمحور حول العميل', null, null, null, 180, false),
('solutions', 'solutions.text.019', 'text', 'The iNex experience starts with your actual circumstances, not the assumption that everyone needs the same pro', 'تبدأ تجربة iNex من واقع احتياجاتك، لا من افتراض أن الجميع يحتاجون إلى الحماية نفسها. سواء كنت تراجع وثيقة شخصي', 'The iNex experience starts with your actual circumstances, not the assumption that everyone needs the same protection. Whether you are reviewing a personal policy, thinking about your family or looking at employee benefits, begin by understanding what is already in place and what needs a question or review.', 'تبدأ تجربة iNex من واقع احتياجاتك، لا من افتراض أن الجميع يحتاجون إلى الحماية نفسها. سواء كنت تراجع وثيقة شخصية، أو تفكر في أسرتك، أو تتعامل مع مزايا الموظفين، فإن الخطوة الأولى هي فهم ما هو قائم وما الذي يحتاج إلى سؤال أو مراجعة.', null, null, null, 190, false),
('solutions', 'solutions.text.020', 'text', 'For individuals', 'للأفراد', 'For individuals', 'للأفراد', null, null, null, 200, false),
('solutions', 'solutions.text.021', 'text', 'Understand your insurance needs, learn key concepts and review available policy information and requests in on', 'افهم احتياجاتك التأمينية، وتعرّف على المفاهيم الأساسية، وراجع معلومات وثائقك وطلباتك المتاحة من مكان واحد. است', 'Understand your insurance needs, learn key concepts and review available policy information and requests in one place. Use the content and tools to prepare more specific questions before discussing your options.', 'افهم احتياجاتك التأمينية، وتعرّف على المفاهيم الأساسية، وراجع معلومات وثائقك وطلباتك المتاحة من مكان واحد. استخدم المحتوى والأدوات لتجهيز أسئلة أكثر تحديدًا قبل مناقشة خياراتك.', null, null, null, 210, false),
('solutions', 'solutions.text.022', 'text', 'Insurance awareness and tips', 'التوعية والنصائح التأمينية', 'Insurance awareness and tips', 'التوعية والنصائح التأمينية', null, null, null, 220, false),
('solutions', 'solutions.text.023', 'text', 'Personal protection assessment', 'تقييم الحماية الشخصية', 'Personal protection assessment', 'تقييم الحماية الشخصية', null, null, null, 230, false),
('solutions', 'solutions.text.024', 'text', 'Policy and renewal tracking', 'متابعة الوثائق والتجديدات', 'Policy and renewal tracking', 'متابعة الوثائق والتجديدات', null, null, null, 240, false),
('solutions', 'solutions.text.025', 'text', 'For families', 'للأسر', 'For families', 'للأسر', null, null, null, 250, false),
('solutions', 'solutions.text.026', 'text', 'Start by recognising how needs differ across family members, responsibilities and circumstances, then explore ', 'ابدأ بفهم اختلاف احتياجات أفراد الأسرة حسب العمر والمسؤوليات والظروف، ثم استكشف أنواع الحماية التي يمكن مناقشت', 'Start by recognising how needs differ across family members, responsibilities and circumstances, then explore protection options to discuss with an insurance broker.', 'ابدأ بفهم اختلاف احتياجات أفراد الأسرة حسب العمر والمسؤوليات والظروف، ثم استكشف أنواع الحماية التي يمكن مناقشتها مع وسيط التأمين.', null, null, null, 260, false),
('solutions', 'solutions.text.027', 'text', 'Understand family protection needs', 'فهم احتياجات الحماية الأسرية', 'Understand family protection needs', 'فهم احتياجات الحماية الأسرية', null, null, null, 270, false),
('solutions', 'solutions.text.028', 'text', 'Request an insurance consultation', 'طلب استشارة تأمينية', 'Request an insurance consultation', 'طلب استشارة تأمينية', null, null, null, 280, false),
('solutions', 'solutions.text.029', 'text', 'Review insurance quotations', 'مراجعة عروض التأمين', 'Review insurance quotations', 'مراجعة عروض التأمين', null, null, null, 290, false),
('solutions', 'solutions.text.030', 'text', 'For employees', 'للموظفين', 'For employees', 'للموظفين', null, null, null, 300, false),
('solutions', 'solutions.text.031', 'text', 'Learn about employee-related insurance coverage and use the customer tools available in iNex to understand wha', 'تعرّف على التغطيات والمعلومات المرتبطة بمزايا الموظفين، واستخدم أدوات العميل المتاحة داخل iNex لفهم ما هو مسجل', 'Learn about employee-related insurance coverage and use the customer tools available in iNex to understand what is recorded and what may need clarification.', 'تعرّف على التغطيات والمعلومات المرتبطة بمزايا الموظفين، واستخدم أدوات العميل المتاحة داخل iNex لفهم ما هو مسجل وما يحتاج إلى استفسار.', null, null, null, 310, false),
('solutions', 'solutions.text.032', 'text', 'Understand coverage and benefits', 'فهم التغطية والمنافع', 'Understand coverage and benefits', 'فهم التغطية والمنافع', null, null, null, 320, false),
('solutions', 'solutions.text.033', 'text', 'Refer to policies and information', 'الرجوع إلى الوثائق والمعلومات', 'Refer to policies and information', 'الرجوع إلى الوثائق والمعلومات', null, null, null, 330, false),
('solutions', 'solutions.text.034', 'text', 'Request support or guidance', 'طلب الدعم أو الاستشارة', 'Request support or guidance', 'طلب الدعم أو الاستشارة', null, null, null, 340, false),
('solutions', 'solutions.text.035', 'text', 'For organisations', 'للجهات المؤسسية', 'For organisations', 'للجهات المؤسسية', null, null, null, 350, false),
('solutions', 'solutions.text.036', 'text', 'The iNex application includes a Corporate HR Hub for corporate insurance and HR contexts, subject to each orga', 'يتضمن تطبيق iNex وحدة Corporate HR Hub لدعم سياقات التأمين المؤسسي والموارد البشرية، وفق الصلاحيات والإعدادات ', 'The iNex application includes a Corporate HR Hub for corporate insurance and HR contexts, subject to each organisation’s permissions and configuration. Benefit details and eligibility remain governed by the applicable policies and agreements.', 'يتضمن تطبيق iNex وحدة Corporate HR Hub لدعم سياقات التأمين المؤسسي والموارد البشرية، وفق الصلاحيات والإعدادات المتاحة لكل جهة. وتظل تفاصيل المزايا والاستحقاق خاضعة للوثائق والاتفاقات المعمول بها.', null, null, null, 360, false),
('solutions', 'solutions.text.037', 'text', 'Group medical insurance context', 'سياق التأمين الطبي الجماعي', 'Group medical insurance context', 'سياق التأمين الطبي الجماعي', null, null, null, 370, false),
('solutions', 'solutions.text.038', 'text', 'Organise company policies and documents', 'تنظيم وثائق ومستندات الشركة', 'Organise company policies and documents', 'تنظيم وثائق ومستندات الشركة', null, null, null, 380, false),
('solutions', 'solutions.text.039', 'text', 'Follow requests and updates', 'متابعة الطلبات والتحديثات', 'Follow requests and updates', 'متابعة الطلبات والتحديثات', null, null, null, 390, false),
('solutions', 'solutions.text.040', 'text', 'DESIGNED AROUND REAL NEEDS', 'DESIGNED AROUND REAL NEEDS', 'DESIGNED AROUND REAL NEEDS', 'DESIGNED AROUND REAL NEEDS', null, null, null, 400, false),
('solutions', 'solutions.text.041', 'text', 'iNex helps you build an organised understanding of your needs without assuming that individuals, families, emp', 'تساعدك iNex على بناء فهم أولي ومنظم لاحتياجاتك، لكنها لا تفترض أن احتياجات الأفراد أو الأسر أو الموظفين متطابق', 'iNex helps you build an organised understanding of your needs without assuming that individuals, families, employees or organisations are all the same. Start with what matters to you, then review the details with the appropriate provider.', 'تساعدك iNex على بناء فهم أولي ومنظم لاحتياجاتك، لكنها لا تفترض أن احتياجات الأفراد أو الأسر أو الموظفين متطابقة. ابدأ بما يهمك، ثم راجع التفاصيل مع الجهة المختصة.', null, null, null, 410, false),
('solutions', 'solutions.text.042', 'text', 'Before choosing cover', 'قبل اختيار التغطية', 'Before choosing cover', 'قبل اختيار التغطية', null, null, null, 420, false),
('solutions', 'solutions.text.043', 'text', 'Gather your questions, understand the terminology and identify the priorities you want to discuss when request', 'اجمع أسئلتك، وافهم المصطلحات، وحدد الأولويات التي تريد مناقشتها عند طلب عرض أو استشارة.', 'Gather your questions, understand the terminology and identify the priorities you want to discuss when requesting a quote or consultation.', 'اجمع أسئلتك، وافهم المصطلحات، وحدد الأولويات التي تريد مناقشتها عند طلب عرض أو استشارة.', null, null, null, 430, false),
('solutions', 'solutions.text.044', 'text', 'While managing a policy', 'أثناء إدارة الوثيقة', 'While managing a policy', 'أثناء إدارة الوثيقة', null, null, null, 440, false),
('solutions', 'solutions.text.045', 'text', 'Keep relevant information and documents organised, and pay attention to policy periods, renewals and changes t', 'احتفظ بالمعلومات والمستندات ذات الصلة، وانتبه إلى فترات السريان والتجديد والتغييرات التي قد تستدعي المراجعة.', 'Keep relevant information and documents organised, and pay attention to policy periods, renewals and changes that may call for a review.', 'احتفظ بالمعلومات والمستندات ذات الصلة، وانتبه إلى فترات السريان والتجديد والتغييرات التي قد تستدعي المراجعة.', null, null, null, 450, false),
('solutions', 'solutions.text.046', 'text', 'When you need support', 'عند الحاجة إلى المساعدة', 'When you need support', 'عند الحاجة إلى المساعدة', null, null, null, 460, false),
('solutions', 'solutions.text.047', 'text', 'Use the service channels available in the app, and contact your broker or insurer for help interpreting terms ', 'استخدم قنوات الخدمة المتاحة في التطبيق، وارجع إلى الوسيط أو شركة التأمين لتفسير الشروط أو متابعة المطالبة.', 'Use the service channels available in the app, and contact your broker or insurer for help interpreting terms or following a claim.', 'استخدم قنوات الخدمة المتاحة في التطبيق، وارجع إلى الوسيط أو شركة التأمين لتفسير الشروط أو متابعة المطالبة.', null, null, null, 470, false),
('solutions', 'solutions.text.048', 'text', 'MAKE EACH STEP COUNT', 'MAKE EACH STEP COUNT', 'MAKE EACH STEP COUNT', 'MAKE EACH STEP COUNT', null, null, null, 480, false),
('solutions', 'solutions.text.049', 'text', 'Make every step in your journey clearer and more useful.', 'اجعل كل خطوة في رحلتك أكثر وضوحًا وفائدة.', 'Make every step in your journey<br><em>clearer and more useful.</em>', 'اجعل كل خطوة في رحلتك<br><em>أكثر وضوحًا وفائدة.</em>', null, null, null, 490, false),
('solutions', 'solutions.text.050', 'text', 'iNex helps you organise the questions and information you need before discussing options. The goal is not to r', 'تساعدك iNex على تنظيم الأسئلة والمعلومات التي تحتاج إليها قبل مناقشة الخيارات. ليست الغاية اختيار منتج بسرعة، ', 'iNex helps you organise the questions and information you need before discussing options. The goal is not to rush into a product choice, but to build a clearer understanding of what may fit your needs and what should be verified.', 'تساعدك iNex على تنظيم الأسئلة والمعلومات التي تحتاج إليها قبل مناقشة الخيارات. ليست الغاية اختيار منتج بسرعة، بل الوصول إلى فهم أفضل لما يناسب احتياجك وما ينبغي التحقق منه.', null, null, null, 500, false),
('solutions', 'solutions.text.051', 'text', 'Define what matters', 'حدد ما يهمك', 'Define what matters', 'حدد ما يهمك', null, null, null, 510, false),
('solutions', 'solutions.text.052', 'text', 'Start with the people, property or responsibilities you want to protect, and consider how a potential risk cou', 'ابدأ بالأشخاص أو الممتلكات أو الالتزامات التي تريد حمايتها، وفكّر في أثر الخطر المحتمل على حياتك أو أسرتك أو ع', 'Start with the people, property or responsibilities you want to protect, and consider how a potential risk could affect your life, family or work.', 'ابدأ بالأشخاص أو الممتلكات أو الالتزامات التي تريد حمايتها، وفكّر في أثر الخطر المحتمل على حياتك أو أسرتك أو عملك.', null, null, null, 520, false),
('solutions', 'solutions.text.053', 'text', 'Review what you already have', 'راجع ما لديك', 'Review what you already have', 'راجع ما لديك', null, null, null, 530, false),
('solutions', 'solutions.text.054', 'text', 'Understand existing policies, benefits and limits. Do not assume that holding a policy means every need or cir', 'افهم الوثائق والمنافع والحدود القائمة، ولا تفترض أن وجود وثيقة يعني أن كل احتياج مغطى أو أن كل الحالات مشمولة.', 'Understand existing policies, benefits and limits. Do not assume that holding a policy means every need or circumstance is covered.', 'افهم الوثائق والمنافع والحدود القائمة، ولا تفترض أن وجود وثيقة يعني أن كل احتياج مغطى أو أن كل الحالات مشمولة.', null, null, null, 540, false),
('solutions', 'solutions.text.055', 'text', 'Discuss options on a clear basis', 'ناقش الخيارات على أساس واضح', 'Discuss options on a clear basis', 'ناقش الخيارات على أساس واضح', null, null, null, 550, false),
('solutions', 'solutions.text.056', 'text', 'Prepare your questions and ask the broker or insurer to explain differences in coverage, exclusions, procedure', 'جهّز أسئلتك واطلب توضيح الفروق في التغطية والاستثناءات والإجراءات والشروط من الوسيط أو شركة التأمين قبل اتخاذ ', 'Prepare your questions and ask the broker or insurer to explain differences in coverage, exclusions, procedures and terms before you decide.', 'جهّز أسئلتك واطلب توضيح الفروق في التغطية والاستثناءات والإجراءات والشروط من الوسيط أو شركة التأمين قبل اتخاذ القرار.', null, null, null, 560, false),
