('company', 'company.image.03', 'image', 'Fawzya Hesham, COO and Co-Founder of iNex', 'Fawzya Hesham, COO and Co-Founder of iNex', null, null, 'Fawzya Hesham, COO and Co-Founder of iNex', 'Fawzya Hesham, COO and Co-Founder of iNex', '/assets/fawzya-hesham.jpg', 1030, false),
('company', 'company.text.042', 'text', 'COO & Co-Founder', 'الرئيس التنفيذي للعمليات والشريك المؤسس', 'COO & Co-Founder', 'الرئيس التنفيذي للعمليات والشريك المؤسس', null, null, null, 420, false),
('company', 'company.text.043', 'text', 'Fawzya Hesham', 'فوزية هشام', 'Fawzya Hesham', 'فوزية هشام', null, null, null, 430, false),
('company', 'company.text.044', 'text', 'Fawzya Hesham leads iNex’s operational direction and coordinates execution across priorities, supporting opera', 'تقود فوزية هشام التوجه التشغيلي لـ iNex وتنسيق تنفيذ الأولويات بين فرق العمل، بما يدعم كفاءة العمليات واتساق ت', 'Fawzya Hesham leads iNex’s operational direction and coordinates execution across priorities, supporting operational consistency, customer experience and the quality of digital service delivery.', 'تقود فوزية هشام التوجه التشغيلي لـ iNex وتنسيق تنفيذ الأولويات بين فرق العمل، بما يدعم كفاءة العمليات واتساق تجربة العملاء وجودة تقديم الخدمات الرقمية.', null, null, null, 440, false),
('company', 'company.text.045', 'text', 'Operations & execution', 'العمليات والتنفيذ', 'Operations & execution', 'العمليات والتنفيذ', null, null, null, 450, false),
('company', 'company.text.046', 'text', 'Service quality', 'جودة الخدمة', 'Service quality', 'جودة الخدمة', null, null, null, 460, false),
('company', 'company.text.047', 'text', 'Fawzya Hesham on LinkedIn ↗', 'LinkedIn فوزية هشام ↗', 'Fawzya Hesham on LinkedIn ↗', 'LinkedIn فوزية هشام ↗', null, null, null, 470, false),
('company', 'company.text.048', 'text', 'Create your account ↗', 'أنشئ حسابك وابدأ مع iNex ↗', 'Create your account ↗', 'أنشئ حسابك وابدأ مع iNex ↗', null, null, null, 480, false),
('company', 'company.text.049', 'text', 'HOW WE BUILD', 'HOW WE BUILD', 'HOW WE BUILD', 'HOW WE BUILD', null, null, null, 490, false),
('company', 'company.text.050', 'text', 'We measure technology by the value it creates for customers. That means starting with real questions, being tr', 'نقيس قيمة التقنية بمدى فائدتها للعميل. لذلك نبدأ بالأسئلة الحقيقية، ونوضح حدود الخدمة، ونصمم كل خطوة لتكون مفه', 'We measure technology by the value it creates for customers. That means starting with real questions, being transparent about service boundaries and designing each step to be clear and useful.', 'نقيس قيمة التقنية بمدى فائدتها للعميل. لذلك نبدأ بالأسئلة الحقيقية، ونوضح حدود الخدمة، ونصمم كل خطوة لتكون مفهومة وقابلة للاستخدام.', null, null, null, 500, false),
('company', 'company.text.051', 'text', 'Clarity before complexity', 'الوضوح قبل التعقيد', 'Clarity before complexity', 'الوضوح قبل التعقيد', null, null, null, 510, false),
('company', 'company.text.052', 'text', 'We explain concepts in direct language, surface what needs attention and help customers distinguish general in', 'نشرح المفاهيم بلغة مباشرة، ونُظهر ما يحتاج إلى مراجعة، ونساعد العميل على التمييز بين المعلومة العامة وشروط الو', 'We explain concepts in direct language, surface what needs attention and help customers distinguish general information from policy terms.', 'نشرح المفاهيم بلغة مباشرة، ونُظهر ما يحتاج إلى مراجعة، ونساعد العميل على التمييز بين المعلومة العامة وشروط الوثيقة.', null, null, null, 520, false),
('company', 'company.text.053', 'text', 'The customer at the centre', 'العميل في مركز التجربة', 'The customer at the centre', 'العميل في مركز التجربة', null, null, null, 530, false),
('company', 'company.text.054', 'text', 'We start with the customer’s needs, questions and context—not a list of technical features. Every tool should ', 'نبدأ من احتياجات العميل وأسئلته وسياقه، لا من قائمة خصائص تقنية. يجب أن تقوده كل أداة إلى فهم أفضل أو خطوة عمل', 'We start with the customer’s needs, questions and context—not a list of technical features. Every tool should lead to better understanding or a useful next step.', 'نبدأ من احتياجات العميل وأسئلته وسياقه، لا من قائمة خصائص تقنية. يجب أن تقوده كل أداة إلى فهم أفضل أو خطوة عملية مفيدة.', null, null, null, 540, false),
('company', 'company.text.055', 'text', 'Responsibility and transparency', 'المسؤولية والشفافية', 'Responsibility and transparency', 'المسؤولية والشفافية', null, null, null, 550, false),
('company', 'company.text.056', 'text', 'We make the roles of iNex, the broker and the insurer clear, and never promise coverage, acceptance or pricing', 'نوضح دور iNex ودور الوسيط وشركة التأمين، ولا نَعِد بتغطية أو قبول أو سعر خارج ما تحدده الوثيقة ومقدم التأمين.', 'We make the roles of iNex, the broker and the insurer clear, and never promise coverage, acceptance or pricing beyond what the policy and provider determine.', 'نوضح دور iNex ودور الوسيط وشركة التأمين، ولا نَعِد بتغطية أو قبول أو سعر خارج ما تحدده الوثيقة ومقدم التأمين.', null, null, null, 560, false),
('company', 'company.text.057', 'text', 'WHAT GUIDES THE EXPERIENCE', 'WHAT GUIDES THE EXPERIENCE', 'WHAT GUIDES THE EXPERIENCE', 'WHAT GUIDES THE EXPERIENCE', null, null, null, 570, false),
('company', 'company.text.058', 'text', 'We believe good technology makes complex things clearer.', 'نؤمن أن التقنية الجيدة تجعل الأمور المعقدة أوضح.', 'We believe good technology<br><em>makes complex things clearer.</em>', 'نؤمن أن التقنية الجيدة<br><em>تجعل الأمور المعقدة أوضح.</em>', null, null, null, 580, false),
('company', 'company.text.059', 'text', 'In insurance, a polished interface is not enough. Real value comes from information people can understand, ste', 'في التأمين، لا تكفي الواجهة الجميلة وحدها. القيمة الحقيقية تأتي من معلومات يمكن فهمها، وخطوات يمكن متابعتها، و', 'In insurance, a polished interface is not enough. Real value comes from information people can understand, steps they can follow and clear service boundaries. That is why the iNex experience is guided by practical principles that balance innovation with trust.', 'في التأمين، لا تكفي الواجهة الجميلة وحدها. القيمة الحقيقية تأتي من معلومات يمكن فهمها، وخطوات يمكن متابعتها، وحدود خدمة واضحة. لذلك ترتكز تجربة iNex على مبادئ عملية توازن بين الابتكار والثقة.', null, null, null, 590, false),
('company', 'company.text.060', 'text', 'Knowledge before choice', 'المعرفة قبل الاختيار', 'Knowledge before choice', 'المعرفة قبل الاختيار', null, null, null, 600, false),
('company', 'company.text.061', 'text', 'We place awareness at the beginning of the journey so customers can understand key concepts and prepare questi', 'نضع التوعية في بداية الرحلة حتى يتمكن العميل من فهم المفاهيم الأساسية وتجهيز أسئلته قبل مناقشة التغطية أو الخي', 'We place awareness at the beginning of the journey so customers can understand key concepts and prepare questions before discussing cover or options.', 'نضع التوعية في بداية الرحلة حتى يتمكن العميل من فهم المفاهيم الأساسية وتجهيز أسئلته قبل مناقشة التغطية أو الخيارات.', null, null, null, 610, false),
('company', 'company.text.062', 'text', 'Connection instead of fragmentation', 'الترابط بدل التشتت', 'Connection instead of fragmentation', 'الترابط بدل التشتت', null, null, null, 620, false),
('company', 'company.text.063', 'text', 'We connect educational content, needs-review tools, policy information and available services in a more organi', 'نربط المحتوى التوعوي وأدوات مراجعة الاحتياجات ومعلومات الوثائق والخدمات المتاحة ضمن مسار رقمي أكثر تنظيمًا.', 'We connect educational content, needs-review tools, policy information and available services in a more organised digital journey.', 'نربط المحتوى التوعوي وأدوات مراجعة الاحتياجات ومعلومات الوثائق والخدمات المتاحة ضمن مسار رقمي أكثر تنظيمًا.', null, null, null, 630, false),
('company', 'company.text.064', 'text', 'Clarity of roles', 'الوضوح في الأدوار', 'Clarity of roles', 'الوضوح في الأدوار', null, null, null, 640, false),
('company', 'company.text.065', 'text', 'We clarify what iNex provides and what belongs to the broker or insurer, while keeping the issued policy as th', 'نوضح ما تقدمه iNex وما يعود إلى الوسيط أو شركة التأمين، ونحافظ على أن تكون شروط الوثيقة الصادرة هي المرجع عند ', 'We clarify what iNex provides and what belongs to the broker or insurer, while keeping the issued policy as the reference for interpreting cover.', 'نوضح ما تقدمه iNex وما يعود إلى الوسيط أو شركة التأمين، ونحافظ على أن تكون شروط الوثيقة الصادرة هي المرجع عند تفسير التغطية.', null, null, null, 650, false),
('company', 'company.text.066', 'text', 'Innovation that serves customers', 'ابتكار يخدم العميل', 'Innovation that serves customers', 'ابتكار يخدم العميل', null, null, null, 660, false),
('company', 'company.text.067', 'text', 'We measure tools by how well they help customers understand, organise and reach a next step—not by the number ', 'نقيس قيمة الأدوات بمدى مساعدتها للعميل على الفهم والتنظيم والوصول إلى الخطوة التالية، وليس بعدد الخصائص أو الم', 'We measure tools by how well they help customers understand, organise and reach a next step—not by the number of features or technical terms.', 'نقيس قيمة الأدوات بمدى مساعدتها للعميل على الفهم والتنظيم والوصول إلى الخطوة التالية، وليس بعدد الخصائص أو المصطلحات التقنية.', null, null, null, 670, false),
