('contact', 'contact.text.017', 'text', 'InsurNex', 'InsurNex', 'InsurNex', 'InsurNex', null, null, null, 170, false),
('contact', 'contact.text.018', 'text', 'CONTACT iNEX', 'تواصل معنا', 'CONTACT iNEX', 'تواصل معنا', null, null, null, 180, false),
('contact', 'contact.text.019', 'text', 'Open iNex to request a consultation or follow up with customer services. If your question concerns coverage, a', 'افتح تطبيق iNex لطلب استشارة أو متابعة خدمة العملاء. وإذا كان سؤالك يتعلق بتغطية أو مطالبة أو شرط في وثيقتك، ف', 'Open iNex to request a consultation or follow up with customer services. If your question concerns coverage, a claim or a policy condition, contact the insurer or broker identified in your documents.', 'افتح تطبيق iNex لطلب استشارة أو متابعة خدمة العملاء. وإذا كان سؤالك يتعلق بتغطية أو مطالبة أو شرط في وثيقتك، فارجع إلى شركة التأمين أو الوسيط الموضح في مستنداتك.', null, null, null, 190, false),
('contact', 'contact.text.020', 'text', 'Here to help you understand.', 'نحن هنا لمساعدتك على الفهم.', 'Here to help you understand.', 'نحن هنا لمساعدتك على الفهم.', null, null, null, 200, false),
('contact', 'contact.text.021', 'text', 'For enquiries about insurance, policies or consultations, open iNex and use the available customer contact ser', 'للاستفسارات المتعلقة بالتأمين أو الوثائق أو طلب الاستشارة، انتقل إلى تطبيق iNex واستخدم خدمات التواصل المتاحة.', 'For enquiries about insurance, policies or consultations, open iNex and use the available customer contact services.', 'للاستفسارات المتعلقة بالتأمين أو الوثائق أو طلب الاستشارة، انتقل إلى تطبيق iNex واستخدم خدمات التواصل المتاحة.', null, null, null, 210, false),
('contact', 'contact.text.022', 'text', 'Create an iNex account ↗', 'إنشاء حساب في iNex ↗', 'Create an iNex account ↗', 'إنشاء حساب في iNex ↗', null, null, null, 220, false),
('contact', 'contact.text.023', 'text', 'Do not send personal data or sensitive insurance documents through public channels.', 'لا ترسل بيانات شخصية أو مستندات تأمينية حساسة عبر قنوات عامة.', 'Do not send personal data or sensitive insurance documents through public channels.', 'لا ترسل بيانات شخصية أو مستندات تأمينية حساسة عبر قنوات عامة.', null, null, null, 230, false),
('contact', 'contact.text.024', 'text', 'Request a consultation', 'طلب استشارة', 'Request a consultation', 'طلب استشارة', null, null, null, 240, false),
('contact', 'contact.text.025', 'text', 'You can submit an insurance consultation request from within the app.', 'يمكنك إرسال طلب استشارة تأمينية من داخل التطبيق.', 'You can submit an insurance consultation request from within the app.', 'يمكنك إرسال طلب استشارة تأمينية من داخل التطبيق.', null, null, null, 250, false),
('contact', 'contact.text.026', 'text', 'Policy support', 'متابعة الوثائق', 'Policy support', 'متابعة الوثائق', null, null, null, 260, false),
('contact', 'contact.text.027', 'text', 'Use your iNex account to review registered policies and documents.', 'استخدم حسابك داخل iNex لمراجعة الوثائق والمستندات المسجلة.', 'Use your iNex account to review registered policies and documents.', 'استخدم حسابك داخل iNex لمراجعة الوثائق والمستندات المسجلة.', null, null, null, 270, false),
('contact', 'contact.text.028', 'text', 'General enquiries', 'الاستفسارات العامة', 'General enquiries', 'الاستفسارات العامة', null, null, null, 280, false),
('contact', 'contact.text.029', 'text', 'For questions about your policy, coverage limits or claims, start with the broker or insurer shown in your doc', 'للاستفسار عن وثيقتك أو حدود التغطية أو المطالبات، ابدأ بالوسيط أو شركة التأمين الموضحين في مستنداتك. أما الأسئ', 'For questions about your policy, coverage limits or claims, start with the broker or insurer shown in your documents. For help using iNex, use the support channels available inside the application.', 'للاستفسار عن وثيقتك أو حدود التغطية أو المطالبات، ابدأ بالوسيط أو شركة التأمين الموضحين في مستنداتك. أما الأسئلة المتعلقة باستخدام iNex، فاستخدم قنوات الدعم المتاحة داخل التطبيق.', null, null, null, 290, false),
('contact', 'contact.text.030', 'text', 'FIND THE RIGHT ROUTE', 'FIND THE RIGHT ROUTE', 'FIND THE RIGHT ROUTE', 'FIND THE RIGHT ROUTE', null, null, null, 300, false),
('contact', 'contact.text.031', 'text', 'The right contact depends on the nature of your enquiry. This guide helps you direct your question to the most', 'تختلف الجهة المناسبة بحسب طبيعة استفسارك. يساعدك هذا الدليل على توجيه السؤال إلى القناة الأكثر صلة، مع حماية ب', 'The right contact depends on the nature of your enquiry. This guide helps you direct your question to the most relevant channel while protecting your personal information and documents.', 'تختلف الجهة المناسبة بحسب طبيعة استفسارك. يساعدك هذا الدليل على توجيه السؤال إلى القناة الأكثر صلة، مع حماية بياناتك ومستنداتك.', null, null, null, 310, false),
('contact', 'contact.text.032', 'text', 'iNex services', 'خدمات iNex', 'iNex services', 'خدمات iNex', null, null, null, 320, false),
('contact', 'contact.text.033', 'text', 'For account setup, awareness tools or digital-service questions, use the support channels shown inside the app', 'للاستفسار عن إنشاء الحساب أو استخدام أدوات التوعية أو الخدمات الرقمية، استخدم قنوات الدعم الظاهرة داخل التطبيق', 'For account setup, awareness tools or digital-service questions, use the support channels shown inside the app.', 'للاستفسار عن إنشاء الحساب أو استخدام أدوات التوعية أو الخدمات الرقمية، استخدم قنوات الدعم الظاهرة داخل التطبيق.', null, null, null, 330, false),
('contact', 'contact.text.034', 'text', 'Policy and coverage', 'الوثيقة والتغطية', 'Policy and coverage', 'الوثيقة والتغطية', null, null, null, 340, false),
('contact', 'contact.text.035', 'text', 'For a policy clause, coverage limit, exclusion or claim follow-up, contact the insurer or broker named in your', 'لشرح بند أو حد تغطية أو استثناء أو متابعة مطالبة، تواصل مع شركة التأمين أو الوسيط المحدد في وثيقتك.', 'For a policy clause, coverage limit, exclusion or claim follow-up, contact the insurer or broker named in your policy.', 'لشرح بند أو حد تغطية أو استثناء أو متابعة مطالبة، تواصل مع شركة التأمين أو الوسيط المحدد في وثيقتك.', null, null, null, 350, false),
('contact', 'contact.text.036', 'text', 'Consultation request', 'طلب استشارة', 'Consultation request', 'طلب استشارة', null, null, null, 360, false),
('contact', 'contact.text.037', 'text', 'You can submit a consultation request from within iNex and describe the subject you need to discuss without sh', 'يمكنك إرسال طلب استشارة من داخل تطبيق iNex، وتوضيح الموضوع الذي تحتاج إلى مناقشته دون مشاركة بيانات حساسة في ق', 'You can submit a consultation request from within iNex and describe the subject you need to discuss without sharing sensitive information through a public channel.', 'يمكنك إرسال طلب استشارة من داخل تطبيق iNex، وتوضيح الموضوع الذي تحتاج إلى مناقشته دون مشاركة بيانات حساسة في قناة عامة.', null, null, null, 370, false),
('contact', 'contact.text.038', 'text', 'BEFORE YOU REACH OUT', 'BEFORE YOU REACH OUT', 'BEFORE YOU REACH OUT', 'BEFORE YOU REACH OUT', null, null, null, 380, false),
('contact', 'contact.text.039', 'text', 'A clearer enquiry starts with the right information.', 'استفسار أوضح يبدأ بتجهيز المعلومة المناسبة.', 'A clearer enquiry starts<br><em>with the right information.</em>', 'استفسار أوضح يبدأ<br><em>بتجهيز المعلومة المناسبة.</em>', null, null, null, 390, false),
('contact', 'contact.text.040', 'text', 'Describing the nature of your enquiry helps direct it to the right channel and reduces unnecessary back-and-fo', 'يساعدك توضيح طبيعة استفسارك على الوصول إلى الجهة المناسبة وتقليل تكرار الخطوات. لا ترسل بيانات شخصية أو مستندا', 'Describing the nature of your enquiry helps direct it to the right channel and reduces unnecessary back-and-forth. Do not send personal information or sensitive insurance documents through public channels.', 'يساعدك توضيح طبيعة استفسارك على الوصول إلى الجهة المناسبة وتقليل تكرار الخطوات. لا ترسل بيانات شخصية أو مستندات تأمينية حساسة عبر القنوات العامة.', null, null, null, 400, false),
('contact', 'contact.text.041', 'text', 'Identify your question', 'حدد نوع سؤالك', 'Identify your question', 'حدد نوع سؤالك', null, null, null, 410, false),
('contact', 'contact.text.042', 'text', 'Is your question about using iNex, understanding an insurance topic, a policy condition or a claim follow-up? ', 'هل يتعلق الأمر باستخدام تطبيق iNex، أم بمعلومة توعوية، أم بشرط في وثيقة أو متابعة مطالبة؟ تحديد الموضوع يساعد ', 'Is your question about using iNex, understanding an insurance topic, a policy condition or a claim follow-up? Identifying the subject helps direct you more effectively.', 'هل يتعلق الأمر باستخدام تطبيق iNex، أم بمعلومة توعوية، أم بشرط في وثيقة أو متابعة مطالبة؟ تحديد الموضوع يساعد على توجيهك بصورة أفضل.', null, null, null, 420, false),
('contact', 'contact.text.043', 'text', 'Prepare your reference', 'جهّز مرجعك', 'Prepare your reference', 'جهّز مرجعك', null, null, null, 430, false),
('contact', 'contact.text.044', 'text', 'When asking about a policy, have its reference number, insurer name and official contact details ready. Share ', 'عند التواصل بشأن وثيقة، احتفظ برقمها واسم شركة التأمين وبيانات التواصل الرسمية. شارك التفاصيل المطلوبة فقط عبر', 'When asking about a policy, have its reference number, insurer name and official contact details ready. Share only the information needed through the appropriate secure channel.', 'عند التواصل بشأن وثيقة، احتفظ برقمها واسم شركة التأمين وبيانات التواصل الرسمية. شارك التفاصيل المطلوبة فقط عبر القناة المناسبة والآمنة.', null, null, null, 440, false),
('contact', 'contact.text.045', 'text', 'Follow up with the right provider', 'تابع مع الجهة المختصة', 'Follow up with the right provider', 'تابع مع الجهة المختصة', null, null, null, 450, false),
('contact', 'contact.text.046', 'text', 'Use iNex channels for application and available-service enquiries. Contact your broker or insurer to interpret', 'استخدم قنوات iNex للاستفسارات المتعلقة بالتطبيق والخدمات المتاحة، وارجع إلى الوسيط أو شركة التأمين لتفسير الشر', 'Use iNex channels for application and available-service enquiries. Contact your broker or insurer to interpret policy terms or follow up on claims.', 'استخدم قنوات iNex للاستفسارات المتعلقة بالتطبيق والخدمات المتاحة، وارجع إلى الوسيط أو شركة التأمين لتفسير الشروط أو متابعة المطالبات.', null, null, null, 460, false),
