('resources', 'resources.text.016', 'text', 'A knowledge space for understanding insurance fundamentals, reading policies, following digital transformation', 'مساحة معرفية تساعدك على فهم أساسيات التأمين، وقراءة الوثائق، ومتابعة التحولات الرقمية وإدارة المخاطر. نركز على', 'A knowledge space for understanding insurance fundamentals, reading policies, following digital transformation and exploring risk management. We focus on practical explanations and the questions that connect concepts to real needs.', 'مساحة معرفية تساعدك على فهم أساسيات التأمين، وقراءة الوثائق، ومتابعة التحولات الرقمية وإدارة المخاطر. نركز على الشرح العملي والأسئلة التي تساعدك على ربط المفهوم بحياتك واحتياجاتك.', null, null, null, 160, false),
('resources', 'resources.text.017', 'text', 'Start with the essentials', 'ابدأ بالأساسيات', 'Start with the essentials', 'ابدأ بالأساسيات', null, null, null, 170, false),
('resources', 'resources.text.018', 'text', 'Use these practical guides to understand what a policy says, compare insurance options on a like-for-like basi', 'ابدأ بهذه الأدلة العملية لفهم ما تنص عليه وثيقتك، ومقارنة الخيارات التأمينية على أساس متكافئ، والاستعداد للخطو', 'Use these practical guides to understand what a policy says, compare insurance options on a like-for-like basis and prepare for the steps that matter when you need to make a claim. These are educational starting points; the wording of your own policy and current provider guidance remain authoritative.', 'ابدأ بهذه الأدلة العملية لفهم ما تنص عليه وثيقتك، ومقارنة الخيارات التأمينية على أساس متكافئ، والاستعداد للخطوات المهمة عند تقديم المطالبة. هذه نقاط انطلاق تعليمية، وتظل وثيقتك وإرشادات مقدم التأمين هي المرجع المعتمد.', null, null, null, 180, false),
('resources', 'resources.text.019', 'text', 'Insurance fundamentals', 'أساسيات التأمين', 'Insurance fundamentals', 'أساسيات التأمين', null, null, null, 190, false),
('resources', 'resources.text.020', 'text', 'Policies, coverage, claims and managing protection needs.', 'مفاهيم الوثائق والتغطيات والمطالبات وإدارة الاحتياجات.', 'Policies, coverage, claims and managing protection needs.', 'مفاهيم الوثائق والتغطيات والمطالبات وإدارة الاحتياجات.', null, null, null, 200, false),
('resources', 'resources.text.021', 'text', 'InsurTech', 'التقنية التأمينية', 'InsurTech', 'التقنية التأمينية', null, null, null, 210, false),
('resources', 'resources.text.022', 'text', 'How digital tools can organise operations and improve experiences.', 'كيف تدعم الأدوات الرقمية تنظيم العمليات وتحسين التجربة.', 'How digital tools can organise operations and improve experiences.', 'كيف تدعم الأدوات الرقمية تنظيم العمليات وتحسين التجربة.', null, null, null, 220, false),
('resources', 'resources.text.023', 'text', 'Risk management', 'إدارة المخاطر', 'Risk management', 'إدارة المخاطر', null, null, null, 230, false),
('resources', 'resources.text.024', 'text', 'Principles of risk assessment and understanding insurance needs.', 'مبادئ تقييم المخاطر وفهم الاحتياجات التأمينية.', 'Principles of risk assessment and understanding insurance needs.', 'مبادئ تقييم المخاطر وفهم الاحتياجات التأمينية.', null, null, null, 240, false),
('resources', 'resources.text.025', 'text', 'START HERE', 'ابدأ من هنا', 'START HERE', 'ابدأ من هنا', null, null, null, 250, false),
('resources', 'resources.text.026', 'text', 'You do not need to become an insurance expert to take a more informed next step. Start by understanding your p', 'لا تحتاج إلى أن تصبح خبيرًا في التأمين حتى تتخذ خطوة أكثر وعيًا. ابدأ بفهم الوثيقة، ثم تعرّف على ما تقارنه، وا', 'You do not need to become an insurance expert to take a more informed next step. Start by understanding your policy, learn what to compare and prepare before you need to use your cover.', 'لا تحتاج إلى أن تصبح خبيرًا في التأمين حتى تتخذ خطوة أكثر وعيًا. ابدأ بفهم الوثيقة، ثم تعرّف على ما تقارنه، واستعد قبل أن تحتاج إلى استخدام التغطية.', null, null, null, 260, false),
('resources', 'resources.text.027', 'text', 'How to read your policy', 'كيف تقرأ وثيقتك؟', 'How to read your policy', 'كيف تقرأ وثيقتك؟', null, null, null, 270, false),
('resources', 'resources.text.028', 'text', 'Start with the policy parties, period of cover, sum insured and benefits schedule. Then review limits, exclusi', 'ابدأ بأطراف الوثيقة وفترة السريان ومبلغ التأمين وجدول المنافع. بعد ذلك راجع الحدود والاستثناءات والتحملات وشرو', 'Start with the policy parties, period of cover, sum insured and benefits schedule. Then review limits, exclusions, deductibles and notification and claims conditions.', 'ابدأ بأطراف الوثيقة وفترة السريان ومبلغ التأمين وجدول المنافع. بعد ذلك راجع الحدود والاستثناءات والتحملات وشروط الإخطار والمطالبة.', null, null, null, 280, false),
('resources', 'resources.text.029', 'text', 'How to compare insurance offers', 'كيف تقارن بين العروض؟', 'How to compare insurance offers', 'كيف تقارن بين العروض؟', null, null, null, 290, false),
('resources', 'resources.text.030', 'text', 'Compare coverage type and limits, exclusions, provider networks and claims procedures on a like-for-like basis', 'قارن نوع التغطية وحدودها والاستثناءات وشبكة مقدمي الخدمة وإجراءات المطالبة على أساس متكافئ، ولا تفصل السعر عن ', 'Compare coverage type and limits, exclusions, provider networks and claims procedures on a like-for-like basis. Do not separate price from the benefits you receive.', 'قارن نوع التغطية وحدودها والاستثناءات وشبكة مقدمي الخدمة وإجراءات المطالبة على أساس متكافئ، ولا تفصل السعر عن المنافع التي تحصل عليها.', null, null, null, 300, false),
('resources', 'resources.text.031', 'text', 'What to do when making a claim', 'ماذا تفعل عند المطالبة؟', 'What to do when making a claim', 'ماذا تفعل عند المطالبة؟', null, null, null, 310, false),
('resources', 'resources.text.032', 'text', 'Check the notification process and deadlines in your policy. Keep correspondence, documents and reference numb', 'راجع طريقة الإبلاغ والمهل المحددة في الوثيقة، واحتفظ بالمراسلات والمستندات وأرقام المتابعة، وتواصل مع الوسيط أ', 'Check the notification process and deadlines in your policy. Keep correspondence, documents and reference numbers, and contact your broker or insurer when needed.', 'راجع طريقة الإبلاغ والمهل المحددة في الوثيقة، واحتفظ بالمراسلات والمستندات وأرقام المتابعة، وتواصل مع الوسيط أو شركة التأمين عند الحاجة.', null, null, null, 320, false),
('resources', 'resources.text.033', 'text', 'EXPLORE THE BIGGER PICTURE', 'استكشف الصورة الأوسع', 'EXPLORE THE BIGGER PICTURE', 'استكشف الصورة الأوسع', null, null, null, 330, false),
('resources', 'resources.text.034', 'text', 'Data, digital platforms and artificial intelligence are changing how information is organised and services are', 'تؤثر البيانات والمنصات الرقمية والذكاء الاصطناعي في طريقة تنظيم المعلومات وتقديم الخدمات داخل قطاع التأمين. لك', 'Data, digital platforms and artificial intelligence are changing how information is organised and services are delivered across insurance. Technology does not remove the need to understand coverage and terms; used responsibly, it can make knowledge and services easier to navigate.', 'تؤثر البيانات والمنصات الرقمية والذكاء الاصطناعي في طريقة تنظيم المعلومات وتقديم الخدمات داخل قطاع التأمين. لكن التقنية لا تلغي أهمية فهم التغطية والشروط؛ بل تجعل الوصول إلى المعرفة والخدمة أكثر تنظيمًا عندما تُستخدم بمسؤولية.', null, null, null, 340, false),
('resources', 'resources.text.035', 'text', 'Insurance literacy', 'الثقافة التأمينية', 'Insurance literacy', 'الثقافة التأمينية', null, null, null, 350, false),
('resources', 'resources.text.036', 'text', 'Understand how policies work, what coverage, exclusions and claims mean, and which questions help you review y', 'افهم كيف تعمل الوثيقة، وما الذي تعنيه التغطية والاستثناءات والمطالبات، وما الأسئلة التي تساعدك على مراجعة احتي', 'Understand how policies work, what coverage, exclusions and claims mean, and which questions help you review your needs.', 'افهم كيف تعمل الوثيقة، وما الذي تعنيه التغطية والاستثناءات والمطالبات، وما الأسئلة التي تساعدك على مراجعة احتياجاتك.', null, null, null, 360, false),
('resources', 'resources.text.037', 'text', 'Digital services', 'الخدمات الرقمية', 'Digital services', 'الخدمات الرقمية', null, null, null, 370, false),
('resources', 'resources.text.038', 'text', 'Explore how digital experiences can organise information and requests and improve access to services while kee', 'تعرّف على كيف يمكن للتجارب الرقمية أن تنظم المعلومات والطلبات وتسهّل الوصول إلى الخدمة، مع الحفاظ على وضوح الأ', 'Explore how digital experiences can organise information and requests and improve access to services while keeping roles and data use clear.', 'تعرّف على كيف يمكن للتجارب الرقمية أن تنظم المعلومات والطلبات وتسهّل الوصول إلى الخدمة، مع الحفاظ على وضوح الأدوار والبيانات.', null, null, null, 380, false),
('resources', 'resources.text.039', 'text', 'Risk management', 'إدارة المخاطر', 'Risk management', 'إدارة المخاطر', null, null, null, 390, false),
('resources', 'resources.text.040', 'text', 'Start by identifying what you want to protect, understanding potential sources of risk and connecting them to ', 'ابدأ بتحديد ما تريد حمايته، وفهم مصادر الخطر المحتملة، وربط ذلك بقرارات الحماية التي تحتاج إلى مراجعة متخصصة.', 'Start by identifying what you want to protect, understanding potential sources of risk and connecting them to protection decisions that may need specialist review.', 'ابدأ بتحديد ما تريد حمايته، وفهم مصادر الخطر المحتملة، وربط ذلك بقرارات الحماية التي تحتاج إلى مراجعة متخصصة.', null, null, null, 400, false),
('resources', 'resources.text.041', 'text', 'InsurTech', 'التقنية التأمينية', 'InsurTech', 'التقنية التأمينية', null, null, null, 410, false),
('resources', 'resources.text.042', 'text', 'Explore how technology can connect education, assessment and service in a more coherent journey, while the pol', 'استكشف دور التقنية في بناء رحلات أكثر ترابطًا بين المعرفة والتقييم والخدمة، مع بقاء الوثيقة وشروط مقدم التأمين', 'Explore how technology can connect education, assessment and service in a more coherent journey, while the policy and insurer’s terms remain authoritative.', 'استكشف دور التقنية في بناء رحلات أكثر ترابطًا بين المعرفة والتقييم والخدمة، مع بقاء الوثيقة وشروط مقدم التأمين هي المرجع.', null, null, null, 420, false),
