('resources', 'resources.text.052', 'text', 'Notice', 'تنويه', 'Notice', 'تنويه', null, null, null, 520, false),
('resources', 'resources.text.053', 'text', 'iNex is a technology platform connected to insurance brokerage services; it is not an insurer and does not iss', 'iNex منصة تقنية مرتبطة بخدمات وساطة التأمين، وليست شركة تأمين ولا تصدر الوثائق بنفسها.', 'iNex is a technology platform connected to insurance brokerage services; it is not an insurer and does not issue policies itself.', 'iNex منصة تقنية مرتبطة بخدمات وساطة التأمين، وليست شركة تأمين ولا تصدر الوثائق بنفسها.', null, null, null, 530, false),
