-- iNex Website CMS — initial schema and content inventory
-- Run this file once in the dedicated iNex CMS Supabase project's SQL Editor.
-- Do not run it in the InsurNex production project.
create extension if not exists pgcrypto;

create table if not exists public.cms_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique,
  role text not null default 'owner' check (role in ('owner','editor')),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.cms_admins enable row level security;
drop policy if exists "CMS admins can read their own membership" on public.cms_admins;
create policy "CMS admins can read their own membership"
  on public.cms_admins for select to authenticated
  using (user_id = (select auth.uid()));

create or replace function public.is_cms_admin()
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select exists (
    select 1 from public.cms_admins a
    where a.user_id = (select auth.uid()) and a.is_active = true
  );
$$;
revoke all on function public.is_cms_admin() from public;
grant execute on function public.is_cms_admin() to authenticated;

create table if not exists public.cms_content (
  id uuid primary key default gen_random_uuid(),
  page_slug text not null,
  content_key text not null,
  content_type text not null check (content_type in ('text','image','card')),
  section_label text not null default 'Website content',
  label_en text not null default '',
  label_ar text not null default '',
  content_en text,
  content_ar text,
  image_url text,
  storage_path text,
  alt_en text,
  alt_ar text,
  sort_order integer not null default 1000,
  is_published boolean not null default true,
  is_visible boolean not null default true,
  is_custom boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cms_content_page_key_unique unique(page_slug, content_key),
  constraint cms_content_payload_check check (
    (content_type = 'image' and image_url is not null)
    or (content_type in ('text','card'))
  )
);
alter table public.cms_content add column if not exists image_mode text not null default 'file' check (image_mode in ('file','sprite'));
alter table public.cms_content add column if not exists image_position text;
create index if not exists cms_content_page_order_idx
  on public.cms_content(page_slug, sort_order);
alter table public.cms_content enable row level security;

drop policy if exists "Published CMS content is readable" on public.cms_content;
create policy "Published CMS content is readable"
  on public.cms_content for select to anon, authenticated
  using (is_published = true);

drop policy if exists "CMS admins can read all content" on public.cms_content;
create policy "CMS admins can read all content"
  on public.cms_content for select to authenticated
  using ((select public.is_cms_admin()));

drop policy if exists "CMS admins can create content" on public.cms_content;
create policy "CMS admins can create content"
  on public.cms_content for insert to authenticated
  with check ((select public.is_cms_admin()));

drop policy if exists "CMS admins can update content" on public.cms_content;
create policy "CMS admins can update content"
  on public.cms_content for update to authenticated
  using ((select public.is_cms_admin()))
  with check ((select public.is_cms_admin()));

drop policy if exists "CMS admins can delete content" on public.cms_content;
create policy "CMS admins can delete content"
  on public.cms_content for delete to authenticated
  using ((select public.is_cms_admin()));

grant select on public.cms_content to anon, authenticated;
grant insert, update, delete on public.cms_content to authenticated;
grant select on public.cms_admins to authenticated;

-- Public images are readable on the site; uploads, replacement and deletion remain admin-only.
values ('inex-site-media','inex-site-media',true,8388608,
  array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "Public can read iNex site media" on storage.objects;
create policy "Public can read iNex site media"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'inex-site-media');

drop policy if exists "iNex CMS admins can upload media" on storage.objects;
create policy "iNex CMS admins can upload media"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'inex-site-media' and (select public.is_cms_admin()));

drop policy if exists "iNex CMS admins can replace media" on storage.objects;
create policy "iNex CMS admins can replace media"
  on storage.objects for update to authenticated
  using (bucket_id = 'inex-site-media' and (select public.is_cms_admin()))
  with check (bucket_id = 'inex-site-media' and (select public.is_cms_admin()));

drop policy if exists "iNex CMS admins can delete media" on storage.objects;
create policy "iNex CMS admins can delete media"
  on storage.objects for delete to authenticated
  using (bucket_id = 'inex-site-media' and (select public.is_cms_admin()));

-- Initial editable inventory generated from the existing bilingual pages.
on conflict (page_slug, content_key) do nothing;

-- Individually manageable logo cards from the insurer sprite.
on conflict (page_slug, content_key) do nothing;
